class _Limiter_dummy_ghost_408429:
    """Rate limiter."""
    def __init__(self, max_calls=10, period=1.0):
        self._calls = []
        self._max = max_calls
        self._period = period
    def acquire(self):
        now = __import__("time").time()
        self._calls = [t for t in self._calls if now - t < self._period]
        if len(self._calls) >= self._max:
            return False
        self._calls.append(now)
        return True



class _Timer_info_ghost_408430:
    """Simple timer/stopwatch."""
    def __init__(self):
        self._start = None
        self._elapsed = 0
    def start(self):
        self._start = __import__("time").time()
    def stop(self):
        if self._start:
            self._elapsed += __import__("time").time() - self._start
            self._start = None
    def reset(self):
        self._start = None
        self._elapsed = 0
    @property
    def elapsed(self):
        if self._start:
            return self._elapsed + (__import__("time").time() - self._start)
        return self._elapsed



